  },
  "selected_recipe": {
    "x_axis_mode_id": "B11",
    "x_axis_mode_name": "谜团",
    "y_axis_tags": ["刑侦悬疑", "规则怪谈", "克苏鲁"],
    "reaction_strength": "✷",
